(8407, 266, 'What is a feasibility study?', 'An assessment of whether the project is practical and viable', 'A coding session', 'A marketing plan', 'A training course', 'A', 'Feasibility examines technical, economic, and operational viability.', 'BEGINNER', 1, 'MCQ', 1),
(8408, 266, 'Which document states the project''s purpose?', 'The project charter or problem statement', 'The code file', 'The test report', 'The invoice', 'A', 'The charter formally authorizes and defines the project.', 'BEGINNER', 1, 'MCQ', 1),
(8409, 266, 'What is a deliverable?', 'A tangible output produced by the project', 'A team meeting', 'A bug', 'A server log', 'A', 'Deliverables are the concrete results of the project.', 'BEGINNER', 1, 'MCQ', 1),
(8410, 266, 'What is a milestone?', 'A significant point in the project schedule', 'A code error', 'A database query', 'A hardware part', 'A', 'Milestones mark important progress points.', 'BEGINNER', 1, 'MCQ', 1),
