(8417, 266, 'What does the term ''return on investment'' (ROI) evaluate?', 'The financial benefit of a project relative to its cost', 'The number of lines of code', 'The team size', 'The meeting count', 'A', 'ROI justifies project investment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(8418, 266, 'Which factor indicates a project is technically feasible?', 'The required technology and skills are available', 'The office is large', 'The team is friendly', 'The budget is unused', 'A', 'Technical feasibility depends on available technology and expertise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(8419, 266, 'What is the purpose of a project justification?', 'To explain why the project should be undertaken', 'To delete data', 'To format drives', 'To write code', 'A', 'Justification states the reasons and benefits of the project.', 'INTERMEDIATE', 2, 'MCQ', 1),
(8420, 266, 'What does a project''s ''in-scope'' versus ''out-of-scope'' distinction do?', 'Prevents scope creep by defining boundaries', 'Increases work', 'Hides requirements', 'Deletes features', 'A', 'Clear scope boundaries keep the project focused.', 'INTERMEDIATE', 2, 'MCQ', 1),
